import Foundation
import zlib

/// Original rectangle glyph, generated by Scripts/describe-owned-test-font.py.
/// No third-party font bytes. Runtime Swift assembly needs no Python dependency.
enum OwnedTestFontFixture {
  private static func short(_ value: Int) -> [UInt8] {
    [UInt8(truncatingIfNeeded: value >> 8), UInt8(truncatingIfNeeded: value)]
  }

  private static func word(_ value: UInt32) -> [UInt8] {
    [24, 16, 8, 0].map { UInt8(truncatingIfNeeded: value >> $0) }
  }

  private static func checksum(_ bytes: [UInt8]) -> UInt32 {
    var padded = bytes
    while padded.count % 4 != 0 { padded.append(0) }
    var value: UInt32 = 0
    for index in stride(from: 0, to: padded.count, by: 4) {
      value &+= UInt32(padded[index]) << 24 | UInt32(padded[index + 1]) << 16
        | UInt32(padded[index + 2]) << 8 | UInt32(padded[index + 3])
    }
    return value
  }

  static func make(postScriptName: String) -> Data {
    assemble(postScriptName: postScriptName, cff: false)
  }

  static func makeOTF(postScriptName: String) -> Data {
    assemble(postScriptName: postScriptName, cff: true)
  }

  private static func assemble(postScriptName: String, cff: Bool) -> Data {
    var templates = [
      "OS/2": "AAMCWAGQAAUABAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAQAAAAAAAAAAAAAAAD8/Pz8AAAB4AHgDIP84AAADIADIAAAAAAAAAAAAAAAAAAAAIAAA",
      "cmap": "AAAAAgAAAAMAAAAUAAMAAQAAABQABAAgAAAABAAEAAEAAAB4//8AAAB4////iQABAAAAAA==",
      "glyf": "AAEAZAAAAfQCvAADAAAzIREhZAGQ/nACvAA=",
      "head": "AAEAAAABAAAAAAAAXw889QADA+gAAAAAAAAAAAAAAAAAAAAAAGQAAAH0ArwAAAADAAIAAAAA",
      "hhea": "AAEAAAMg/zgAAAJYAGQAZAH0AAEAAAAAAAAAAAAAAAAAAAAB",
      "hmtx": "AlgAAABk",
      "loca": "AAAAAAAN",
      "maxp": "AAEAAAACAAQAAQAAAAAAAgAAAAAAAAAAAAAAAAAAAAA=",
      "post": "AAIAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAgAAAFs=",
    ]
    if cff {
      // Reproduced by describe-owned-test-font.py --cff; still our rectangle.
      templates.removeValue(forKey: "glyf")
      templates.removeValue(forKey: "loca")
      templates["maxp"] = "AABQAAAC"
      templates["post"] = "AAMAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA="
      templates["CFF "] = "AQAEAQABAQEqVHlwZWJhclFBMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAAAQEBG/gbAvgbA/gYBO+L+Ij5UAX3FQ+L9y0S9xgRAAEBASpUeXBlYmFyUUEwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMAAAAABZAAIBAQQQ+OwO+OzvFvgk+VD8JAYO"
    }
    var tables = templates.mapValues { Array(Data(base64Encoded: $0)!) }
    if var bytes = tables["CFF "] {
      let placeholder = Array(("TypebarQA" + String(repeating: "0", count: 32)).utf8)
      let replacement = Array(postScriptName.utf8)
      precondition(replacement.count == placeholder.count)
      var replacements = 0
      for offset in 0...(bytes.count - placeholder.count) {
        if Array(bytes[offset..<(offset + placeholder.count)]) == placeholder {
          bytes.replaceSubrange(offset..<(offset + placeholder.count), with: replacement)
          replacements += 1
        }
      }
      precondition(replacements == 2) // Name INDEX and shared family/full-name string.
      tables["CFF "] = bytes
    }
    let names = [(1, postScriptName), (2, "Regular"), (3, postScriptName),
      (4, postScriptName + " Regular"), (6, postScriptName)]
    var records: [UInt8] = [], strings: [UInt8] = []
    for (id, name) in names {
      let bytes = name.utf16.flatMap { short(Int($0)) }
      records += short(3) + short(1) + short(0x0409) + short(id)
        + short(bytes.count) + short(strings.count)
      strings += bytes
    }
    tables["name"] = short(0) + short(names.count) + short(6 + records.count) + records + strings
    // Nine CFF or ten TrueType tables, with the same largest power of two (8).
    precondition(tables.count == (cff ? 9 : 10))
    let header = word(cff ? 0x4F54544F : 0x00010000) + short(tables.count)
      + short(128) + short(3) + short(tables.count * 16 - 128)
    var directory: [UInt8] = [], payload: [UInt8] = []
    var headOffset = 0
    for tag in tables.keys.sorted() {
      let bytes = tables[tag]!
      let offset = header.count + tables.count * 16 + payload.count
      if tag == "head" { headOffset = offset }
      directory += Array(tag.utf8) + word(checksum(bytes)) + word(UInt32(offset)) + word(UInt32(bytes.count))
      payload += bytes
      while payload.count % 4 != 0 { payload.append(0) }
    }
    var font = header + directory + payload
    // OpenType head checksum adjustment; see the official otff specification.
    font.replaceSubrange((headOffset + 8)..<(headOffset + 12),
      with: word(0xB1B0AFBA &- checksum(font)))
    return Data(font)
  }

  /// WOFF 1.0 permits storing tables uncompressed (compLength == origLength).
  /// Keep the identical original SFNT tables and checksums; only repackage.
  static func makeWOFF(postScriptName: String, compressed: Bool = false) -> Data {
    let sfnt = Array(make(postScriptName: postScriptName))
    func integer(at offset: Int) -> Int {
      sfnt[offset..<(offset + 4)].reduce(0) { ($0 << 8) | Int($1) }
    }
    let count = Int(sfnt[4]) << 8 | Int(sfnt[5])
    var directory: [UInt8] = [], payload: [UInt8] = []
    for index in 0..<count {
      let record = 12 + index * 16
      let offset = integer(at: record + 8), length = integer(at: record + 12)
      let original = Array(sfnt[offset..<(offset + length)])
      var table = original
      if compressed {
        var outputLength = compressBound(uLong(original.count))
        var output = [UInt8](repeating: 0, count: Int(outputLength))
        let status = original.withUnsafeBufferPointer { source in
          output.withUnsafeMutableBufferPointer { destination in
            compress2(destination.baseAddress, &outputLength, source.baseAddress,
              uLong(original.count), Z_BEST_COMPRESSION)
          }
        }
        precondition(status == Z_OK)
        if Int(outputLength) < original.count { table = Array(output.prefix(Int(outputLength))) }
      }
      directory += Array(sfnt[record..<(record + 4)])
        + word(UInt32(44 + count * 20 + payload.count))
        + word(UInt32(table.count)) + word(UInt32(length))
        + Array(sfnt[(record + 4)..<(record + 8)])
      payload += table
      while payload.count % 4 != 0 { payload.append(0) }
    }
    let header = word(0x774F4646) + Array(sfnt[0..<4])
      + word(UInt32(44 + directory.count + payload.count)) + short(count) + short(0)
      + word(UInt32(sfnt.count)) + short(1) + short(0) + Array(repeating: UInt8(0), count: 20)
    precondition(header.count == 44)
    return Data(header + directory + payload)
  }
}
